conn = psycopg2.connect(os.environ["SUPABASE_DB_URL"]); cur = conn.cursor()
cur.execute("""select s.code,s.name,v.sector,so.note from stocks s left join v_stock_sector v on v.code=s.code left join sector_override so on so.code=s.code where s.security_type='STOCK'""")
n=0; seen=set()
for c,name,sec,note in cur.fetchall():
    if name in D and (not sec or (note or "").startswith("자동매핑")):
        cur.execute("""insert into sector_override (code,sector_override,note) values (%s,%s,%s) on conflict (code) do update set sector_override=excluded.sector_override, note=excluded.note""",(c,D[name],"수동매핑 2026-11")); n+=1; seen.add(name)
conn.commit()
print(f"# 수동 업종 지정 {n}종목 저장")
print("- 사전에 있으나 DB에서 못 찾음/대상 아님:", [k for k in D if k not in seen])
cur.execute("""select s.code,s.name from stocks s left join v_stock_sector v on v.code=s.code where s.security_type='STOCK' and v.sector is null""")
print("- 아직 미분류:", cur.fetchall())
